import sys, re, json, html
content = sys.stdin.read()

# Check totalRows
total_match = re.search(r'totalRows.:.(\\d+)', content)
if total_match:
    print(f'Total paid courses: {total_match.group(1)}')

# Extract course data from drupal settings JSON
drupal_match = re.search(r'drupal-settings-json.{(.*?)}.</script>', content, re.DOTALL)
if drupal_match:
    settings = drupal_match.group(1)
    total2 = re.search(r'totalRows.:.(\\d+)', settings)
    if total2:
        print(f'From settings - totalRows: {total2.group(1)}')

# Get JSON-LD
jsonld_matches = re.findall(r'<script type=.application/ld\+json.>(.*?)</script>', content, re.DOTALL)
for i, m in enumerate(jsonld_matches):
    try:
        data = json.loads(m)
        if isinstance(data, dict):
            for key in data:
                if isinstance(data[key], list):
                    for item in data[key]:
                        if isinstance(item, dict) and 'itemListElement' in item:
                            print(f'JSON-LD ItemList with {len(item[\"itemListElement\"])} items')
                            for elem in item['itemListElement']:
                                print(f'  {elem[\"position\"]}. {elem[\"url\"]}')
    except:
        pass
